<?php
declare(strict_types=1);
require_once __DIR__.'/_helper.php';
$extraTaskCodes = task_registry_capability_codes('ekstrakurikuler');
$extraTaskPh = implode(',', array_fill(0, count($extraTaskCodes), '?'));
$extraId=(int)($_GET['extra_id']??0);$sesiId=(int)($_GET['sesi_id']??0);$tanggal=(string)($_GET['tanggal']??'');ekstra_require($extraId);
$extra=ekstra_detail($pdo,$extraId);if(!$extra)deny_access();$tp=active_tapel_id($pdo); $sem=active_semester_id($pdo,$tp);if(!$tp||!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$tanggal))deny_access();
$st=$pdo->prepare("SELECT id,tanggal,jam_mulai,jam_selesai,status FROM ekstra_sesi WHERE id=? AND ekstrakurikuler_id=? AND tahun_pelajaran_id=? AND status<>'dibatalkan' LIMIT 1");$st->execute([$sesiId,$extraId,$tp]);$session=$st->fetch();if(!$session)exit('Pertemuan tidak ditemukan.');$tanggal=(string)$session['tanggal'];
$st=$pdo->prepare("SELECT DISTINCT g.id,g.nama,g.nip,jt.nama jenis_tugas FROM tugas_guru tg JOIN guru g ON g.id=tg.guru_id JOIN jenis_tugas jt ON jt.id=tg.jenis_tugas_id WHERE tg.tahun_pelajaran_id=? AND tg.semester_id=? AND tg.target_tipe='ekstrakurikuler' AND tg.target_id=? AND tg.aktif=1 AND jt.kode IN ($extraTaskPh) AND g.status='aktif' ORDER BY g.nama");$st->execute(array_merge([$tp,$sem,$extraId], $extraTaskCodes));$teachers=$st->fetchAll();
$st=$pdo->prepare("SELECT guru_id,status,waktu,keterangan FROM ekstra_pembina_absensi WHERE ekstrakurikuler_id=? AND tahun_pelajaran_id=? AND sesi_id=?");$st->execute([$extraId,$tp,$sesiId]);$logs=[];foreach($st->fetchAll() as $x)$logs[(int)$x['guru_id']]=$x;
$q=$pdo->prepare('SELECT nama FROM tahun_pelajaran WHERE id=?');$q->execute([$tp]);$tpName=(string)($q->fetchColumn()?:'');
$page_title='Absensi Pembina/Pelatih · Pertemuan';require_once __DIR__.'/../layouts/header.php';
?>
