<div class="print-head"><h1>ABSENSI PEMBINA / PELATIH EKSTRAKURIKULER</h1><h2><?=e($extra['nama'])?></h2><p>Tanggal: <?=e(date('d-m-Y',strtotime($tanggal)))?> · Jam: <?=e(substr((string)$session['jam_mulai'],0,5))?><?=!empty($session['jam_selesai'])?' - '.e(substr($session['jam_selesai'],0,5)):''?> · Tapel: <?=e($tpName)?></p></div>
<table class="data-table print-table"><thead><tr><th>No</th><th>Nama Pembina/Pelatih</th><th>Jenis Tugas</th><th>Status</th><th>Jam</th><th>Keterangan</th><th>TTD</th></tr></thead><tbody><?php foreach($teachers as $i=>$g):$l=$logs[(int)$g['id']]??null;?><tr><td><?=$i+1?></td><td><?=e($g['nama'])?></td><td><?=e($g['jenis_tugas'])?></td><td><?=e($l['status']??'')?></td><td><?=e($l['waktu']??'')?></td><td><?=e($l['keterangan']??'')?></td><td class="ttd"></td></tr><?php endforeach;if(!$teachers):?><tr><td colspan="7" class="empty-state">Belum ada pembina/pelatih aktif.</td></tr><?php endif;?></tbody></table>
